: "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "1854b213-3c77-f821-9966-98e585c446d5", "sort_order": 0, "title": "Hawa Mahal (Palace of Winds)", "description": "Whispers of history in wind.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "080dd7df-4a69-3ae5-cf8b-235ac7264ad5", "sort_order": 1, "title": "City Palace", "description": "Royal legacy, echoes of sovereignty.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "7154561d-3222-c992-17ba-cb87c4ea88de", "sort_order": 2, "title": "Observatory / Jantar Mantar", "description": "Celestial marvels, antique astronomy.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "c2b30a19-4102-c823-7880-ed5a5f4f6c1e", "sort_order": 3, "title": "Jal Mahal (Water Palace)", "description": "Peaceful waters, regal reflection.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "ea402890-a50d-86d3-da78-be0ca2897c03", "sort_order": 4, "title": "Amer Fort", "description": "Strength in stone, stories unfold.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "ce8caff3-4fcf-0a9b-73e8-27aa8266933b", "sort_order": 5, "title": "Nahargarh Fort", "description": "Sentinel of Jaipur, royal views.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "pl