": 4, "day_title": "Udaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After having breakfast at hotel, explore the enchanting Lake City of Udaipur:\nOvernight stay at your hotel in Udaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "eb0a2671-9652-2218-13ab-5310e6db0253", "sort_order": 0, "title": "City Palace", "description": "Regal opulence, lakeside grandeur.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "62baac1c-3529-21a5-725e-84d9765f199e", "sort_order": 1, "title": "Pratap Smarak", "description": "Memorial valor, historical tribute.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "d4bcbaad-76bf-3b51-9fcf-a11628bde21a", "sort_order": 2, "title": "Bhartiya Lok Kala Mandal", "description": "Cultural treasure, folk art showcase.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "a2583c48-9467-7681-73af-475c0d7c1ade", "sort_order": 3, "title": "Saheliyon ki Bari", "description": "Garden with peaceful retreat.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "2f13b729-1f15-6802-8012-00a8cbcd4e13", "sort_order": 4, "title": "Jagdish Temple", "description": "Architectural splendor, divine devotion.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "eabf49a8-a8b7-a2ed-b151-2c2c0